def simple_transform(grid):
    h = len(grid)
    w = len(grid[0])

    # Find marker (3 rows same value in same column)
    marker_color = None
    marker_top = marker_left = None

    for r in range(h - 2):
        for c in range(w):
            if grid[r][c] != 0 and grid[r+1][c] == grid[r][c] and grid[r+2][c] == grid[r][c]:
                marker_color = grid[r][c]
                marker_top, marker_left = r, c
                break
        if marker_color:
            break

    if not marker_color:
        return grid

    # Calculate marker width
    marker_width = 1
    for cc in range(1, w):
        if grid[marker_top][marker_left + cc] != 0:
            marker_width += 1
        else:
            break

    marker_height = 3

    # Calculate span
    row_start = marker_top + 1
    row_end = min(h, marker_top + marker_height + 2)

    left_col = marker_left + 1
    right_col = marker_left + marker_width

    output = [[0] * w for _ in range(h)]

    for r in range(row_start, row_end):
        rel = r - row_start

        if rel == 0:
            start = max(0, left_col - 1)
            end = right_col
            for c in range(start, min(w, end + 1)):
                output[r][c] = marker_color

        elif rel == 1:
            output[r][left_col] = marker_color
            output[r][right_col] = marker_color

        elif rel == marker_height:
            start = marker_left
            end = marker_left + marker_width + 1
            for c in range(start, min(w, end + 1)):
                output[r][c] = marker_color

        elif rel == 2:
            for c in range(max(0, left_col - 2), min(w, left_col + 1)):
                output[r][c] = marker_color
            for c in range(right_col, min(w, right_col + 2)):
                output[r][c] = marker_color

        elif rel == 3:
            for c in range(max(0, left_col - 1), min(w, left_col + 1)):
                output[r][c] = marker_color
            for c in range(max(0, right_col - 1), min(w, right_col + 1)):
                output[r][c] = marker_color

    return output

